// TestGet sends GET /api/node/{hostname}/os and checks each answer's response.
func (s *APIGetPublicTestSuite) TestGet() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the example \"An Ubuntu host\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"os.get",
				os.GetInput{},
				servertest.Completed("server1", `{"os_info":{"distribution":"ubuntu","version":"24.04"}}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","os_info":{"distribution":"ubuntu","version":"24.04"},"status":"ok"}]}`,
		},
		{
			Name: "when the example \"An Ubuntu host\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"os.get",
				os.GetInput{},
				servertest.Completed("server1", `{"os_info":{"distribution":"ubuntu","version":"24.04"}}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","os_info":{"distribution":"ubuntu","version":"24.04"},"status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the example \"A Mac\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"os.get",
				os.GetInput{},
				servertest.Completed("server1", `{"os_info":{"distribution":"darwin","version":"15.5"}}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","os_info":{"distribution":"darwin","version":"15.5"},"status":"ok"}]}`,
		},
		{
			Name: "when the example \"A Mac\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"os.get",
				os.GetInput{},
				servertest.Completed("server1", `{"os_info":{"distribution":"darwin","version":"15.5"}}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","os_info":{"distribution":"darwin","version":"15.5"},"status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the host skips it, its row says skipped",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"os.get",
				os.GetInput{},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
		{
			Name: "when the host fails it, its row says failed",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"os.get",
				os.GetInput{},
				servertest.Failed("server1", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"boom","hostname":"server1","status":"failed"}]}`,
		},
		{
			Name: "when the host never answers, its row says timeout",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"os.get",
				os.GetInput{},
				servertest.TimedOut("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"","hostname":"server1","status":"timeout"}]}`,
		},
		{
			Name: "when the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"os.get",
				os.GetInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when broadcast and the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/os",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"os.get",
				os.GetInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
	})
}

